      ro: "Muntele Măslinilor se ridică la est de Orașul Vechi din Ierusalim și oferă nu doar o priveliște uluitoare, ci are și o mare semnificație religioasă pentru iudaism, creștinism și islam.",
      en: "The Mount of Olives rises east of the Old City of Jerusalem and offers not only a breathtaking view but also holds great religious significance for Judaism, Christianity, and Islam.",
      es: "El Monte de los Olivos se eleva al este de la Ciudad Vieja de Jerusalén y ofrece no solo una vista impresionante, sino que también tiene una gran importancia religiosa para el judaísmo, el cristianismo y el islam.",
      pt: "O Monte das Oliveiras ergue-se a leste da Cidade Velha de Jerusalém e oferece não só uma vista deslumbrante, mas também tem grande importância religiosa para o judaísmo, cristianismo e islão.",
